@orders_bp.route("/paged", methods=["GET"])
@require_role("manager")
def paged_orders():
    """List orders with limit/offset pagination."""
    try:
        limit = int(request.args.get("limit", "20"))
        offset = int(request.args.get("offset", "0"))
    except ValueError:
        return jsonify({"error": "limit and offset must be integers"}), 400
    session = get_session()
    user_id = g.user.id  # Assuming the current user is stored in g.user
    rows = session.execute(
        text("SELECT id, user_id, status, total FROM orders WHERE user_id = :user_id LIMIT :limit OFFSET :offset"),
        {"user_id": user_id, "limit": limit, "offset": offset},
    )
    return jsonify([dict(r._mapping) for r in rows])
